	@Test
	void tupleBlankNodesRemainFreshUnderConcurrency() throws Exception {
		try (var executor = Executors.newFixedThreadPool(4)) {
			Callable<Value> invocation = () -> {
				try (var rows = function(RdfParseTupleFunction.Result.TRIPLES).evaluate(VF,
						VF.createLiteral("_:b <urn:p> _:b ."), VF.createLiteral("text/turtle"))) {
					var row = rows.next();
					assertEquals(row.get(0), row.get(2));
					return row.get(0);
				}
			};
			Set<Value> subjects = new HashSet<>();
			for (var future : executor.invokeAll(java.util.Collections.nCopies(16, invocation))) {
				subjects.add(future.get());
			}
			assertEquals(16, subjects.size());
		}
	}

	@Test
	void tupleCloseAndCancellationReleaseTheIteration() {
		var rows = function(RdfParseTupleFunction.Result.TRIPLES).evaluate(VF,
				VF.createLiteral(DATA), VF.createLiteral("text/turtle"));
		try {
			Thread.currentThread().interrupt();
			assertThrows(QueryEvaluationException.class, rows::hasNext);
			assertTrue(Thread.currentThread().isInterrupted());
		} finally {
			Thread.interrupted();
			rows.close();
		}
		assertFalse(rows.hasNext());
		assertThrows(NoSuchElementException.class, rows::next);
	}

	@Test
	void ordinaryLargeGroupIsClonedWithoutChangingItsAlgebra() {
		StringBuilder body = new StringBuilder();
		for (int i = 0; i < 256; i++) {
			body.append("?s <urn:p").append(i).append("> ?v").append(i).append(" . ");
		}
		TupleExpr original = algebra(body.toString());
		TupleExpr before = original.clone();
		TupleExpr rewritten = PropertyFunctionRewriter.rewrite(original, functions());
		assertNotSame(original, rewritten);
		assertEquals(before, original);
		assertEquals(original, rewritten);
	}

	@Test
	void nestedOptionalAndUnionGroupsAreStillRewritten() {
		TupleExpr original = algebra("?s <urn:p> ?o . OPTIONAL { ?doc parse:turtle (?a ?b ?c) } "
				+ "{ ?doc parse:turtle (?d ?e ?f) } UNION { ?x <urn:q> ?y }");
		TupleExpr before = original.clone();
		TupleExpr rewritten = PropertyFunctionRewriter.rewrite(original, functions());
		int[] calls = { 0 };
		rewritten.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meetOther(QueryModelNode node) {
				if (node instanceof TupleFunctionCall) {
					calls[0]++;
				}
				super.meetOther(node);
			}
		});
		assertEquals(2, calls[0]);
		assertEquals(before, original);
	}

