	@Test
	void projectionClosesItsDelegateAndSuppressesSecondaryFailure() {
		var failure = new QueryEvaluationException("read failure");
		var closeFailure = new QueryEvaluationException("close failure");
		var delegate = new LookAheadIteration<BindingSet>() {
			@Override
			protected BindingSet getNextElement() {
				throw failure;
			}

			@Override
			protected void handleClose() {
				throw closeFailure;
			}
		};
		var projected = RdfParseService.projected(delegate, Set.of(), EmptyBindingSet.getInstance());
		assertSame(failure, assertThrows(QueryEvaluationException.class, projected::hasNext));
		assertArrayEquals(new Throwable[] { closeFailure }, failure.getSuppressed());
		projected.close();
	}

