	@Test
	void batchPlansDoNotLeakBindingValuesOrBlankNodeIdentity() {
		Service request = service("[] parse:content ?doc; parse:format \"text/turtle\" . ?s <urn:p> ?o", false);
		TupleExpr unchanged = request.clone();
		var local = new RdfParseService(parser, Map.of());
		MapBindingSet a = bindings("doc", VF.createLiteral("_:b <urn:p> <urn:a> ."));
		MapBindingSet b = bindings("doc", VF.createLiteral("_:b <urn:p> <urn:b> ."));
		var rows = collect(local.evaluate(request, input(List.of(a, b, a)), null));
		assertEquals(3, rows.size());
		assertEquals(List.of(VF.createIRI("urn:a"), VF.createIRI("urn:b"), VF.createIRI("urn:a")),
				rows.stream().map(row -> row.getValue("o")).toList());
		assertEquals(3, rows.stream().map(row -> row.getValue("s")).distinct().count());
		assertEquals(unchanged, request);
	}

	@Test
	void batchSilentDistinguishesFailureFromAValidNoMatch() {
		Service request = service("[] parse:content ?doc; parse:format \"text/turtle\" . ?s <urn:p> ?o", true);
		var local = new RdfParseService(parser, Map.of());
		MapBindingSet empty = bindings("doc", VF.createLiteral(""));
		MapBindingSet invalid = bindings("doc", VF.createLiteral("broken"));
		MapBindingSet valid = bindings("doc", VF.createLiteral(DATA));
		var rows = collect(local.evaluate(request, input(List.of(empty, invalid, valid)), null));
		assertEquals(2, rows.size());
		assertEquals(invalid, rows.get(0));
		assertEquals(VF.createIRI("urn:s"), rows.get(1).getValue("s"));
	}
